import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"reference/architecture.md","filePath":"reference/architecture.md"}'),s={name:"reference/architecture.md"};function d(r,e,i,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>dbsh is built as a layered .NET solution with clear separation of concerns.</p><h2 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dbsh/</span></span>
<span class="line"><span>  src/</span></span>
<span class="line"><span>    dbsh.Core/             Pure domain model (zero dependencies)</span></span>
<span class="line"><span>    dbsh.Engine/           Script parsing, migration execution</span></span>
<span class="line"><span>    dbsh.Infrastructure/   Database providers, file system config</span></span>
<span class="line"><span>    dbsh.CLI/              The dbsh executable</span></span>
<span class="line"><span>  tests/</span></span>
<span class="line"><span>    dbsh.Engine.Tests/     Unit + integration tests</span></span></code></pre></div><h2 id="layer-diagram" tabindex="-1">Layer diagram <a class="header-anchor" href="#layer-diagram" aria-label="Permalink to &quot;Layer diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│              dbsh.CLI                 │</span></span>
<span class="line"><span>│   Program.cs · Commands · ConsoleHelper  │</span></span>
<span class="line"><span>└──────────────────┬───────────────────────┘</span></span>
<span class="line"><span>                   │ uses</span></span>
<span class="line"><span>        ┌──────────┴─────────┐     ┌──────────────────┐</span></span>
<span class="line"><span>        │    Engine          │     │      Core         │</span></span>
<span class="line"><span>        │ ScriptParser       │────▶│ Entities · Enums  │</span></span>
<span class="line"><span>        │ MigrationExec      │     │ ValueObjects      │</span></span>
<span class="line"><span>        │ InMemory impls     │     └──────────────────┘</span></span>
<span class="line"><span>        └──────────┬─────────┘              ▲</span></span>
<span class="line"><span>                   │ implements             │ implements</span></span>
<span class="line"><span>    ┌──────────────┴────────────────────────┴───────────────┐</span></span>
<span class="line"><span>    │                  Infrastructure                       │</span></span>
<span class="line"><span>    │  Providers/                                           │</span></span>
<span class="line"><span>    │    PostgreSql · SqlServer · MySql · Sqlite            │</span></span>
<span class="line"><span>    │  Relational{Tracker, LockManager, Executor, Audit}    │</span></span>
<span class="line"><span>    │  FileSystemConfigLoader                               │</span></span>
<span class="line"><span>    └───────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="core-dbsh-core" tabindex="-1">Core (<code>dbsh.Core</code>) <a class="header-anchor" href="#core-dbsh-core" aria-label="Permalink to &quot;Core (\`dbsh.Core\`)&quot;">​</a></h2><p>Pure domain model with zero external dependencies.</p><table tabindex="0"><thead><tr><th>Namespace</th><th>Key Types</th></tr></thead><tbody><tr><td><code>Entities</code></td><td><code>MigrationRecord</code>, <code>MigrationAuditEntry</code>, <code>MigrationLock</code></td></tr><tr><td><code>Enums</code></td><td><code>MigrationStatus</code>, <code>MigrationType</code>, <code>AuditAction</code></td></tr><tr><td><code>Interfaces</code></td><td><code>IMigrationTracker</code>, <code>IMigrationLockManager</code>, <code>IAuditLogger</code>, <code>IEnvironmentProvider</code>, <code>IMigrationScriptExecutor</code>, <code>IConfigLoader</code></td></tr><tr><td><code>ValueObjects</code></td><td><code>MigrationConfiguration</code>, <code>EnvironmentConfiguration</code>, <code>DeploymentWindow</code>, <code>ParsedMigration</code>, <code>MigrationContext</code></td></tr><tr><td><code>Exceptions</code></td><td><code>dbshException</code>, <code>ScriptParseException</code>, <code>MigrationConfigurationException</code>, <code>UnsupportedProviderException</code></td></tr></tbody></table><h2 id="engine-dbsh-engine" tabindex="-1">Engine (<code>dbsh.Engine</code>) <a class="header-anchor" href="#engine-dbsh-engine" aria-label="Permalink to &quot;Engine (\`dbsh.Engine\`)&quot;">​</a></h2><p>Application core that orchestrates the migration workflow.</p><table tabindex="0"><thead><tr><th>Class</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>ScriptParser</code></td><td>Parses Flyway-style filenames, generates SHA-256 hashes (LF-normalized), extracts metadata headers, validates content</td></tr><tr><td><code>MigrationExecutor</code></td><td>Orchestrates validation, planning, deployment, rollback, and repair. Coordinates tracker, lock manager, audit log, environment provider, and script executor</td></tr><tr><td><code>InMemoryMigrationTracker</code></td><td>In-memory test double for offline workflows</td></tr><tr><td><code>InMemoryMigrationLockManager</code></td><td>In-memory lock manager</td></tr><tr><td><code>InMemoryAuditLogger</code></td><td>In-memory audit logger</td></tr></tbody></table><h2 id="infrastructure-dbsh-infrastructure" tabindex="-1">Infrastructure (<code>dbsh.Infrastructure</code>) <a class="header-anchor" href="#infrastructure-dbsh-infrastructure" aria-label="Permalink to &quot;Infrastructure (\`dbsh.Infrastructure\`)&quot;">​</a></h2><p>Database-specific implementations and file system access.</p><table tabindex="0"><thead><tr><th>Class</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>PostgreSqlProvider</code></td><td>PostgreSQL via Npgsql. Schema-based module isolation. Lock: <code>INSERT ... ON CONFLICT DO UPDATE</code></td></tr><tr><td><code>SqlServerProvider</code></td><td>SQL Server via Microsoft.Data.SqlClient. Schema-based module isolation. Lock: <code>MERGE ... WITH (HOLDLOCK)</code></td></tr><tr><td><code>MySqlProvider</code></td><td>MySQL via MySqlConnector. Table-prefix module isolation. Lock: <code>INSERT ... ON DUPLICATE KEY UPDATE</code></td></tr><tr><td><code>SqliteProvider</code></td><td>SQLite via Microsoft.Data.Sqlite. Table-prefix module isolation. Lock: <code>INSERT ... ON CONFLICT DO UPDATE</code></td></tr><tr><td><code>RelationalMigrationTracker</code></td><td>Provider-agnostic history tracking using <code>System.Data.Common</code></td></tr><tr><td><code>RelationalMigrationLockManager</code></td><td>Row-based distributed lock with lease expiry</td></tr><tr><td><code>FileSystemConfigLoader</code></td><td>Loads <code>migration.json</code> and <code>environments/*.json</code>, expands <code>\${VAR}</code> tokens</td></tr></tbody></table><h2 id="cli-dbsh-cli" tabindex="-1">CLI (<code>dbsh.CLI</code>) <a class="header-anchor" href="#cli-dbsh-cli" aria-label="Permalink to &quot;CLI (\`dbsh.CLI\`)&quot;">​</a></h2><p>The <code>dbsh</code> executable built with Spectre.Console.Cli.</p><table tabindex="0"><thead><tr><th>Class</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>Program</code></td><td>Entry point, command registration</td></tr><tr><td><code>CliCommandBase</code></td><td>Shared helpers for all commands</td></tr><tr><td><code>CliHost</code></td><td>Composition root — resolves providers, wires implementations</td></tr><tr><td><code>ConsoleHelper</code></td><td>Spectre.Console UI: banners, tables, spinners, gradient text</td></tr><tr><td><code>Theme</code></td><td>Color palette and glyphs</td></tr></tbody></table><h2 id="adding-a-new-provider" tabindex="-1">Adding a new provider <a class="header-anchor" href="#adding-a-new-provider" aria-label="Permalink to &quot;Adding a new provider&quot;">​</a></h2><p>Every database-specific behavior is encapsulated behind <code>IDatabaseProvider</code>. Adding a new provider requires implementing this single interface. The <code>Relational*</code> classes use <code>System.Data.Common</code> base types (<code>DbConnection</code>, <code>DbCommand</code>, <code>DbDataReader</code>) so the same code path works across all engines.</p>`,20)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
